recs=m['RECORDS']
copied=[r for r in recs if r['classification']=='untracked_nonredundant_copy']
print('copied', len(copied))

# families by path prefix
def family(rel):
    rel=rel.replace('\\','/')
    parts=rel.split('/')
    # playwright
    if rel.startswith('.playwright-mcp/') or '/.playwright-mcp/' in rel or parts[0]=='.playwright-mcp':
        return 'playwright_mcp_snapshots'
    if rel.startswith('ui/') or '/ui/' in rel[:20]:
        return 'ui_artifacts'
    if 'section_11_12_8' in rel:
        # campaign leaf
        m2=re.search(r'section_11_12_8_[^/]+', rel)
        return 's11_12_8::'+(m2.group(0) if m2 else 'other')
    if 'section_11_13_5' in rel:
        m2=re.search(r'section_11_13_5_[^/]+', rel)
        return 's11_13_5::'+(m2.group(0) if m2 else 'other')
    if 'section_11_12_9' in rel:
        m2=re.search(r'section_11_12_9_[^/]+', rel)
        return 's11_12_9::'+(m2.group(0) if m2 else 'other')
    if 'integrated_paper_shadow' in rel or 'paper_shadow' in rel:
        return 'paper_shadow'
    if rel.startswith('evidence/ops/') or '/evidence/ops/' in rel:
        m2=re.search(r'evidence/ops/([^/]+)', rel)
        return 'evidence_ops::'+(m2.group(1) if m2 else 'other')
    if rel.startswith('evidence/'):
        m2=re.search(r'evidence/([^/]+)', rel)
        return 'evidence::'+(m2.group(1) if m2 else 'other')
    if rel.startswith('out/') or '/out/' in rel:
        return 'out_generated'
    if rel.endswith(('.png','.jpg','.jpeg','.webp','.gif')):
        return 'images'
    if rel.endswith(('.yml','.yaml')) and 'playwright' not in rel:
        return 'yaml_snapshots_or_config'
    if 'canonical_' in rel and rel.endswith('.json') and 'config/governance' in rel:
        return 'config_governance_json'
    if rel.startswith('config/'):
        return 'config'
    if 'HANDOFF' in rel or rel.endswith('HANDOFF.md'):
        return 'handoff_md'
    ext=pathlib.Path(rel).suffix.lower() or 'noext'
    top=parts[0] if parts else 'root'
    return f'other::{top}::{ext}'

fam=collections.Counter()
wt=collections.Counter()
ext=collections.Counter()
sha_dup=collections.Counter()
present_origin=collections.Counter()
for r in copied:
