print('\n=== ORIGIN_BLOB_MATCH ===', dict(present_origin))
print('unique sha256 among copied', len(sha_dup), 'duplicate-hash files', sum(c-1 for c in sha_dup.values() if c>1), 'max_dup', max(sha_dup.values()))

